primaryQuery:
run: order_items extend {
  join_one: inventory_items is inventory_items
    on inventory_item_id = inventory_items.id
} -> {
  top: 3
  group_by: product_category is inventory_items.product_category
  aggregate: orders is count(order_id)
  order_by: orders desc
}

verifyQuery:
run: inventory_items extend {
  join_many: oi is order_items on id = oi.inventory_item_id
} -> {
  top: 3
  group_by: product_category
  aggregate: orders is count(oi.order_id)
  order_by: orders desc
}
